client_script:
frappe.web_form.after_load = function() {
  var doc = frappe.web_form.doc;
  if (doc && !doc.date_entretien) { frappe.web_form.set_value('date_entretien', frappe.datetime.get_today()); }
  if (doc && doc.name && !String(doc.name).startsWith('new')) {
    var refEl = document.createElement('div');
    refEl.innerHTML = '<div style="margin-bottom:12px;padding:8px 16px;background:#e8f5e9;color:#2e7d32;border-left:4px solid #43a047;border-radius:6px;display:inline-block;font-weight:700;font-size:14px;">\uD83D\uDD27 R\u00e9f. : ' + doc.name + (doc.statut ? '  \u2014  ' + doc.statut : '') + '</div>';
    var w = document.querySelector('.web-form-wrapper') || document.querySelector('.container');
    if (w) w.prepend(refEl);
  }
};
